<?php $base='../';require_once '../config/config.php';require_admin();$rows=db()->query('SELECT m.*,u.full_name,u.email FROM messages m JOIN users u ON u.user_id=m.user_id ORDER BY m.created_at DESC')->fetchAll();$title='Messages';include '../includes/header.php';?><section class="section"><div class="container"><h1>Messages</h1><?php foreach($rows as $r):?><div class="card p-4 mb-3"><div class="d-flex justify-content-between"><strong><?=e($r['subject'])?></strong><small><?=e($r['created_at'])?></small></div><div class="gold"><?=e($r['full_name'])?> · <?=e($r['email'])?></div><p class="mt-2"><?=nl2br(e($r['message']))?></p></div><?php endforeach;?></div></section><?php include '../includes/footer.php';?>
